/**
 * REST benchmark runner — k6 edition.
 *
 * Drop-in replacement for `rest-bench.ts`: identical CLI flags and identical
 * `--json-out` shape, so `run-matrix.ts` consumes it unchanged. The only
 * difference is the load engine — load is generated by an EXTERNAL `k6`
 * process (Go, multi-threaded) instead of an in-process Bun `fetch` client.
 *
 * Rationale: a single-threaded Bun-fetch generator co-located with a Bun
 * server contends for the same JSC runtime + CPU cores and systematically
 * under-reports the bun target (node-based express/fastify don't share the
 * runtime, so they aren't penalised the same way). Measured cross-checks
 * showed the headline result flips with k6. See BENCHMARK.md methodology.
 *
 * Server-side RSS is still sampled here via `ps -o rss=` against the spawned
 * target child; k6 only drives traffic.
 *
 * Requires k6 on PATH (`brew install k6`). The actual mix + request payloads
 * live in `rest-k6.js`.
 */
import { type ChildProcess, spawn, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { createConnection } from 'node:net';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

type Framework = 'rest-nest-express' | 'rest-nest-fastify' | 'rest-nest-bun';

const ALL_TARGETS: readonly Framework[] = [
  'rest-nest-express',
  'rest-nest-fastify',
  'rest-nest-bun',
];

const FRAMEWORK_DIR = join(import.meta.dir, 'frameworks');
const K6_SCRIPT = join(import.meta.dir, 'rest-k6.js');

const OP_KINDS = ['list', 'byId', 'create', 'merge'] as const;
type OpKind = (typeof OP_KINDS)[number];

// Mirrors rest-bench.ts so the report's mix table is identical.
const MIX: ReadonlyArray<{ kind: OpKind; weight: number }> = [
  { kind: 'list', weight: 50 },
  { kind: 'byId', weight: 25 },
  { kind: 'create', weight: 15 },
  { kind: 'merge', weight: 10 },
];

interface Args {
  connections: number;
  duration: number;
  port: number;
  warmupSec: number;
  readyTimeoutMs: number;
  only: Framework[] | null;
  verbose: boolean;
  memSampleMs: number;
  jsonOut: string | null;
}

const DEFAULTS: Args = {
  connections: 50,
  duration: 5,
  port: 3000,
  warmupSec: 1,
  readyTimeoutMs: 30_000,
  only: null,
  verbose: false,
  memSampleMs: 250,
  jsonOut: null,
};

function parseNumber(value: string | undefined, fallback: number): number {
  if (!value) return fallback;
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function isFramework(value: string): value is Framework {
  return (ALL_TARGETS as readonly string[]).includes(value);
}

function parseOnly(raw: string | undefined): Framework[] | null {
  if (!raw) return null;
  const list = raw
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
  const bad = list.filter(s => !isFramework(s));
  if (bad.length) {
    throw new Error(
      `unknown target(s): ${bad.join(', ')}. valid: ${ALL_TARGETS.join(', ')}`,
    );
  }
  return list as Framework[];
}

function printHelp() {
  console.log(`REST benchmark runner (k6)

Usage: bun run tests/bench/rest-bench-k6.ts [options]

Options:
  -c, --connections <n>   k6 VUs (default ${DEFAULTS.connections})
  -d, --duration <sec>    Measurement window in seconds (default ${DEFAULTS.duration})
      --warmup <sec>      Warmup window in seconds (default ${DEFAULTS.warmupSec})
      --port <n>          Port the framework binds to (default ${DEFAULTS.port})
      --ready-timeout <ms>  Time to wait for readiness (default ${DEFAULTS.readyTimeoutMs})
      --mem-interval <ms>   RSS sampling interval (default ${DEFAULTS.memSampleMs}, 0 disables)
      --json-out <path>     Write machine-readable results to <path> after the run
      --only <list>       Comma-separated subset, e.g. --only rest-nest-bun
      -v, --verbose       Stream k6 + child output to this process
  -h, --help              Show this help`);
}

function parseArgs(argv: string[]): Args {
  const args: Args = { ...DEFAULTS };
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelp();
      process.exit(0);
    } else if (token === '-c' || token === '--connections')
      args.connections = parseNumber(argv[++i], args.connections);
    else if (token === '-d' || token === '--duration')
      args.duration = parseNumber(argv[++i], args.duration);
    else if (token === '--port') args.port = parseNumber(argv[++i], args.port);
    else if (token === '--warmup')
      args.warmupSec = parseNumber(argv[++i], args.warmupSec);
    else if (token === '--ready-timeout')
      args.readyTimeoutMs = parseNumber(argv[++i], args.readyTimeoutMs);
    else if (token === '--mem-interval') {
      const raw = argv[++i];
      const n = Number(raw);
      args.memSampleMs = Number.isFinite(n) && n >= 0 ? n : args.memSampleMs;
    } else if (token === '--json-out') args.jsonOut = argv[++i] ?? null;
    else if (token === '--only') args.only = parseOnly(argv[++i]);
    else if (token === '-v' || token === '--verbose') args.verbose = true;
    else throw new Error(`unknown argument: ${token} (try --help)`);
  }
  return args;
}

// ---- result shapes (identical to rest-bench.ts / run-matrix.ts) ----
interface OpResult {
  ok: number;
  errors: number;
  rps: number;
  latencyAvg: number;
  latencyP50: number;
  latencyP90: number;
  latencyP99: number;
  throughputBps: number;
}

interface MemStats {
  idleBytes: number;
  minBytes: number;
  avgBytes: number;
  maxBytes: number;
  p95Bytes: number;
  samples: number;
}

interface Result {
  byOp: Record<OpKind, OpResult>;
  total: OpResult;
  durationMs: number;
  mem: MemStats;
}

// ---- k6 per-op summary (written by rest-k6.js handleSummary) ----
interface K6Op {
  ok: number;
  errors: number;
  bytes: number;
  latAvg: number;
  latP50: number;
  latP90: number;
  latP99: number;
}
type K6Summary = Record<OpKind | 'total', K6Op>;

function toOpResult(o: K6Op, durSec: number): OpResult {
  const ok = o.ok || 0;
  return {
    ok,
    errors: o.errors || 0,
    rps: durSec > 0 ? ok / durSec : 0,
    latencyAvg: o.latAvg || 0,
    latencyP50: o.latP50 || 0,
    latencyP90: o.latP90 || 0,
    latencyP99: o.latP99 || 0,
    throughputBps: durSec > 0 ? (o.bytes || 0) / durSec : 0,
  };
}

// ---- formatting (mirrors rest-bench.ts) ----
function fmt(n: number, digits = 2): string {
  return Number.isFinite(n) ? n.toFixed(digits) : 'n/a';
}
function fmtBytes(n: number): string {
  const abs = Math.abs(n);
  if (abs >= 1024 ** 3) return `${(n / 1024 ** 3).toFixed(2)} GB/s`;
  if (abs >= 1024 ** 2) return `${(n / 1024 ** 2).toFixed(2)} MB/s`;
  if (abs >= 1024) return `${(n / 1024).toFixed(2)} KB/s`;
  return `${n.toFixed(0)} B/s`;
}
function fmtMB(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return 'n/a';
  return `${(bytes / 1024 / 1024).toFixed(1)}MB`;
}

// ---- RSS sampler (server child only) ----
class MemSampler {
  private timer: ReturnType<typeof setInterval> | null = null;
  private inflight = false;
  public readonly samples: number[] = [];
  public idleBytes = 0;

  constructor(
    private readonly pid: number,
    private readonly intervalMs = 250,
  ) {}

  private sampleOnce(): Promise<number> {
    return new Promise(resolve => {
      const proc = spawn('ps', ['-o', 'rss=', '-p', String(this.pid)], {
        stdio: ['ignore', 'pipe', 'ignore'],
      });
      let out = '';
      proc.stdout?.on('data', (c: Buffer) => {
        out += c.toString('utf8');
      });
      proc.once('exit', () => {
        const kb = Number(out.trim());
        resolve(Number.isFinite(kb) && kb > 0 ? kb * 1024 : 0);
      });
      proc.once('error', () => resolve(0));
    });
  }

  async captureIdle() {
    this.idleBytes = await this.sampleOnce();
  }

  start() {
    if (this.timer) return;
    this.timer = setInterval(async () => {
      if (this.inflight) return;
      this.inflight = true;
      try {
        const v = await this.sampleOnce();
        if (v > 0) this.samples.push(v);
      } finally {
        this.inflight = false;
      }
    }, this.intervalMs);
    this.timer.unref?.();
  }

  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

function summarizeMem(s: MemSampler): MemStats {
  if (s.samples.length === 0) {
    return {
      idleBytes: s.idleBytes,
      minBytes: s.idleBytes,
      avgBytes: s.idleBytes,
      maxBytes: s.idleBytes,
      p95Bytes: s.idleBytes,
      samples: 0,
    };
  }
  const sorted = s.samples.slice().sort((a, b) => a - b);
  const sum = sorted.reduce((a, b) => a + b, 0);
  return {
    idleBytes: s.idleBytes,
    minBytes: sorted[0],
    avgBytes: sum / sorted.length,
    maxBytes: sorted[sorted.length - 1],
    p95Bytes: sorted[Math.min(sorted.length - 1, Math.floor(0.95 * sorted.length))],
    samples: sorted.length,
  };
}

// ---- target lifecycle (mirrors rest-bench.ts) ----
function isPortOpen(port: number, host = '127.0.0.1'): Promise<boolean> {
  return new Promise(resolve => {
    const sock = createConnection({ port, host });
    const done = (open: boolean) => {
      sock.destroy();
      resolve(open);
    };
    sock.once('connect', () => done(true));
    sock.once('error', () => done(false));
    sock.setTimeout(250, () => done(false));
  });
}

function pidsOnPort(port: number): number[] {
  const r = spawnSync('lsof', ['-ti', `tcp:${port}`, '-sTCP:LISTEN'], {
    encoding: 'utf8',
  });
  return (r.stdout || '')
    .split('\n')
    .map(s => Number(s.trim()))
    .filter(n => Number.isInteger(n) && n > 0);
}

/**
 * Kill anything still bound to the port and wait until it is actually free.
 * A target's teardown can outlive `killChild`'s window under sustained load;
 * without this, one lingering server poisons every later run (port-in-use).
 */
async function ensurePortFree(port: number, timeoutMs = 10_000): Promise<void> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (!(await isPortOpen(port))) return;
    for (const pid of pidsOnPort(port)) {
      try {
        process.kill(pid, 'SIGKILL');
      } catch {}
    }
    await new Promise(r => setTimeout(r, 200));
  }
}

interface SpawnedTarget {
  child: ChildProcess;
  stderr: string;
}

function spawnTarget(
  framework: Framework,
  port: number,
  verbose: boolean,
): SpawnedTarget {
  // `process.execPath`, not a bare 'bun': the target servers must run on the
  // same runtime as this harness. Resolving 'bun' from PATH silently benchmarked
  // whatever bun happened to be installed, which makes any runtime A/B
  // (e.g. 1.3.x vs 1.4 canary) measure nothing.
  const child = spawn(process.execPath, ['run', join(FRAMEWORK_DIR, `${framework}.ts`)], {
    stdio: verbose ? 'inherit' : ['ignore', 'pipe', 'pipe'],
    env: { ...process.env, PORT: String(port) },
  });
  const result: SpawnedTarget = { child, stderr: '' };
  if (!verbose) {
    const MAX = 16 * 1024;
    child.stderr?.on('data', (chunk: Buffer) => {
      if (result.stderr.length < MAX) {
        result.stderr += chunk.toString('utf8');
        if (result.stderr.length > MAX) {
          result.stderr = `${result.stderr.slice(0, MAX)}\n…[truncated]`;
        }
      }
    });
    child.stdout?.resume();
  }
  return result;
}

async function waitReady(
  baseUrl: string,
  target: SpawnedTarget,
  timeoutMs: number,
): Promise<void> {
  const start = Date.now();
  let lastErr: unknown;
  const probeUrl = `${baseUrl}/todo-items?skip=0&take=1`;
  while (Date.now() - start < timeoutMs) {
    if (target.child.exitCode != null) {
      throw new Error(
        `child exited early with code ${target.child.exitCode}\n--- stderr ---\n${target.stderr || '(empty)'}`,
      );
    }
    try {
      const res = await fetch(probeUrl);
      if (res.status === 200) {
        await res.body?.cancel();
        return;
      }
      lastErr = new Error(`status ${res.status}`);
    } catch (e) {
      lastErr = e;
    }
    await new Promise(r => setTimeout(r, 150));
  }
  throw new Error(
    `server did not become ready: ${probeUrl} (last: ${lastErr instanceof Error ? lastErr.message : String(lastErr)})\n--- stderr ---\n${target.stderr || '(empty)'}`,
  );
}

function killChild(child: ChildProcess): Promise<void> {
  return new Promise(resolve => {
    if (!child || child.exitCode != null || child.killed) return resolve();
    const onExit = () => resolve();
    child.once('exit', onExit);
    try {
      child.kill('SIGTERM');
    } catch {}
    setTimeout(() => {
      try {
        if (child.exitCode == null) child.kill('SIGKILL');
      } catch {}
    }, 800).unref?.();
    setTimeout(() => {
      child.removeListener('exit', onExit);
      resolve();
    }, 2_000).unref?.();
  });
}

// ---- k6 load phase ----
function runK6(
  baseUrl: string,
  vus: number,
  durationSec: number,
  outPath: string | null,
  verbose: boolean,
): Promise<K6Summary | null> {
  return new Promise((resolve, reject) => {
    const env: Record<string, string> = {
      ...process.env,
      BASE: baseUrl,
      VUS: String(vus),
      DUR: `${durationSec}s`,
    };
    if (outPath) env.OUT = outPath;
    const child = spawn('k6', ['run', '--quiet', K6_SCRIPT], {
      stdio: verbose ? 'inherit' : ['ignore', 'ignore', 'pipe'],
      env,
    });
    let stderr = '';
    child.stderr?.on('data', (c: Buffer) => {
      stderr += c.toString('utf8');
    });
    child.once('error', reject);
    child.once('exit', code => {
      if (code !== 0) {
        return reject(
          new Error(`k6 exit ${code}\n--- stderr ---\n${stderr.slice(0, 2000)}`),
        );
      }
      if (!outPath) return resolve(null);
      try {
        resolve(JSON.parse(readFileSync(outPath, 'utf8')) as K6Summary);
      } catch (e) {
        reject(e);
      }
    });
  });
}

function printRun(framework: Framework, args: Args, baseUrl: string, result: Result) {
  const row = (label: string, r: OpResult) => {
    console.log(
      `  ${label.padEnd(8)}  ok=${String(r.ok).padStart(7)}  errors=${String(r.errors).padStart(4)}  RPS=${fmt(r.rps, 0).padStart(6)}  avg=${fmt(r.latencyAvg).padStart(6)}ms  p50=${fmt(r.latencyP50).padStart(6)}ms  p90=${fmt(r.latencyP90).padStart(6)}ms  p99=${fmt(r.latencyP99).padStart(6)}ms`,
    );
  };
  console.log(`\n=== ${framework.toUpperCase()} ===`);
  console.log(`Target: ${baseUrl}`);
  console.log(
    `vus=${args.connections} duration=${args.duration}s warmup=${args.warmupSec}s ` +
      `mix=${MIX.map(o => `${o.kind}:${o.weight}%`).join(' ')}`,
  );
  row('total', result.total);
  for (const k of OP_KINDS) row(k, result.byOp[k]);
  console.log(`  throughput=${fmtBytes(result.total.throughputBps)}`);
  const m = result.mem;
  if (m.samples > 0) {
    const delta = m.avgBytes - m.idleBytes;
    const sign = delta >= 0 ? '+' : '';
    console.log(
      `  rss        idle=${fmtMB(m.idleBytes).padStart(7)}  min=${fmtMB(m.minBytes).padStart(7)}  avg=${fmtMB(m.avgBytes).padStart(7)}  p95=${fmtMB(m.p95Bytes).padStart(7)}  max=${fmtMB(m.maxBytes).padStart(7)}  Δavg=${sign}${fmtMB(Math.abs(delta))}  (${m.samples} samples)`,
    );
  } else if (m.idleBytes > 0) {
    console.log(`  rss        idle=${fmtMB(m.idleBytes)} (no samples — bench too short)`);
  }
}

let active: ChildProcess | null = null;

async function runOne(framework: Framework, args: Args, tmpDir: string): Promise<Result> {
  await ensurePortFree(args.port);
  const target = spawnTarget(framework, args.port, args.verbose);
  active = target.child;
  const baseUrl = `http://127.0.0.1:${args.port}`;
  try {
    await waitReady(baseUrl, target, args.readyTimeoutMs);
    const sampler = target.child.pid
      ? new MemSampler(target.child.pid, args.memSampleMs)
      : null;
    if (sampler) await sampler.captureIdle();
    if (args.warmupSec > 0) {
      await runK6(baseUrl, args.connections, args.warmupSec, null, args.verbose);
    }
    sampler?.start();
    let summary: K6Summary | null;
    try {
      const outPath = join(tmpDir, `${framework}-summary.json`);
      summary = await runK6(
        baseUrl,
        args.connections,
        args.duration,
        outPath,
        args.verbose,
      );
    } finally {
      sampler?.stop();
    }
    if (!summary) throw new Error('k6 produced no summary');

    const durSec = args.duration;
    const byOp = {} as Record<OpKind, OpResult>;
    for (const k of OP_KINDS) byOp[k] = toOpResult(summary[k], durSec);
    const result: Result = {
      byOp,
      total: toOpResult(summary.total, durSec),
      durationMs: durSec * 1000,
      mem: sampler
        ? summarizeMem(sampler)
        : {
            idleBytes: 0,
            minBytes: 0,
            avgBytes: 0,
            maxBytes: 0,
            p95Bytes: 0,
            samples: 0,
          },
    };
    printRun(framework, args, baseUrl, result);
    return result;
  } finally {
    await killChild(target.child);
    active = null;
    await ensurePortFree(args.port);
  }
}

function pctChange(a: number, b: number): string {
  if (!Number.isFinite(a) || !Number.isFinite(b) || b === 0) return 'n/a';
  const p = ((a - b) / b) * 100;
  return `${p >= 0 ? '+' : ''}${p.toFixed(1)}%`;
}

function compare(
  name: string,
  baseline: Result | undefined,
  candidate: Result | undefined,
) {
  console.log(`\n--- ${name} ---`);
  if (!baseline || !candidate) {
    console.log('  (skipped — missing one side)');
    return;
  }
  const row = (label: string, a: OpResult, b: OpResult) => {
    console.log(
      `  ${label.padEnd(8)}  RPS ${fmt(a.rps, 0)} -> ${fmt(b.rps, 0)} (${pctChange(b.rps, a.rps)})  p99 ${fmt(a.latencyP99)} -> ${fmt(b.latencyP99)} (${pctChange(b.latencyP99, a.latencyP99)})`,
    );
  };
  row('total', baseline.total, candidate.total);
  for (const k of OP_KINDS) row(k, baseline.byOp[k], candidate.byOp[k]);
  if (baseline.mem.samples > 0 && candidate.mem.samples > 0) {
    const memRow = (label: string, a: number, b: number) => {
      console.log(
        `  ${label.padEnd(8)}  ${fmtMB(a)} -> ${fmtMB(b)} (${pctChange(b, a)})`,
      );
    };
    memRow('rss avg', baseline.mem.avgBytes, candidate.mem.avgBytes);
    memRow('rss p95', baseline.mem.p95Bytes, candidate.mem.p95Bytes);
    memRow('rss max', baseline.mem.maxBytes, candidate.mem.maxBytes);
  }
}

function installSignalHandlers() {
  const cleanup = (signal: NodeJS.Signals) => {
    if (active) {
      try {
        active.kill('SIGTERM');
      } catch {}
    }
    process.exit(signal === 'SIGINT' ? 130 : 143);
  };
  process.on('SIGINT', () => cleanup('SIGINT'));
  process.on('SIGTERM', () => cleanup('SIGTERM'));
}

function assertK6Available() {
  const probe = spawnSync('k6', ['version'], { stdio: 'ignore' });
  if (probe.error || probe.status !== 0) {
    throw new CliError(
      'k6 not found on PATH. Install it (macOS: `brew install k6`, ' +
        'or see https://k6.io/docs/get-started/installation/) and retry.',
    );
  }
}

class CliError extends Error {}

async function main() {
  let args: Args;
  try {
    args = parseArgs(process.argv.slice(2));
  } catch (e) {
    throw new CliError(e instanceof Error ? e.message : String(e));
  }
  assertK6Available();
  installSignalHandlers();

  const k6Version = (spawnSync('k6', ['version'], { encoding: 'utf8' }).stdout || '')
    .trim()
    .split('\n')[0];
  console.log(`REST benchmark runner (load: ${k6Version || 'k6'})`);

  const tmpDir = mkdtempSync(join(tmpdir(), 'rest-k6-'));
  const targets = args.only ?? [...ALL_TARGETS];
  const results: Partial<Record<Framework, Result>> = {};
  try {
    for (const fw of targets) {
      try {
        results[fw] = await runOne(fw, args, tmpDir);
      } catch (e) {
        console.error(`\n[FAIL] ${fw}:`, e instanceof Error ? e.message : e);
      }
    }
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }

  if (targets.includes('rest-nest-express') && targets.includes('rest-nest-bun')) {
    compare(
      'REST NEST-EXPRESS vs NEST-BUN',
      results['rest-nest-express'],
      results['rest-nest-bun'],
    );
  }
  if (targets.includes('rest-nest-fastify') && targets.includes('rest-nest-bun')) {
    compare(
      'REST NEST-FASTIFY vs NEST-BUN',
      results['rest-nest-fastify'],
      results['rest-nest-bun'],
    );
  }

  if (args.jsonOut) {
    const payload = {
      args: {
        connections: args.connections,
        duration: args.duration,
        warmupSec: args.warmupSec,
        memSampleMs: args.memSampleMs,
      },
      loadGenerator: k6Version || 'k6',
      bunVersion: (globalThis as any).Bun?.version ?? null,
      timestamp: new Date().toISOString(),
      mix: MIX.map(o => ({ kind: o.kind, weight: o.weight })),
      results,
    };
    await Bun.write(args.jsonOut, JSON.stringify(payload, null, 2));
  }
}

main().catch(err => {
  if (err instanceof CliError) {
    console.error(`error: ${err.message}`);
    process.exit(2);
  }
  console.error(err);
  process.exit(1);
});
